'use server';

import { createClient } from '@supabase/supabase-js';
import { createRouteHandlerClient } from '@supabase/auth-helpers-nextjs';
import { cookies } from 'next/headers';
import { z } from 'zod';
import { revalidatePath } from 'next/cache';

// --- CLIENTE SUPABASE (PÚBLICO) ---
const createSupabaseClient = () => {
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

  if (!supabaseUrl || !supabaseAnonKey) {
    throw new Error('Credenciais do Supabase não encontradas. Verifique as variáveis de ambiente.');
  }
  
  return createClient(supabaseUrl, supabaseAnonKey);
};

// --- AÇÕES DE BUSCA DE DADOS ---

export async function getPublicPackages() {
  try {
    const supabase = createSupabaseClient();
    const { data, error } = await supabase
      .from('viagens')
      .select('*')
      .eq('ativo', true)
      .order('destino', { ascending: true });

    if (error) throw error;

    return { packages: data };
  } catch (error) {
    console.error("Erro ao buscar pacotes públicos:", error);
    return { error: "Não foi possível carregar os pacotes." };
  }
}

export async function getPublicPackageById(id: string) {
  try {
    const supabase = createSupabaseClient();
    const { data, error } = await supabase
      .from('viagens')
      .select('*')
      .eq('id', id)
      .limit(1);

    if (error) throw error;

    if (!data || data.length === 0) {
        return { pkg: null, error: `Pacote com ID ${id} não encontrado.` };
    }

    return { pkg: data[0] };

  } catch (e) {
    console.error(`Erro ao buscar pacote por ID ${id}:`, e);
    return { pkg: null, error: "Falha ao buscar dados do pacote." };
  }
}

// --- AÇÕES DE FORMULÁRIO (MUTATIONS) ---

const CreateReservationSchema = z.object({
  packageId: z.string().uuid({ message: 'ID do pacote inválido.' }),
  numTravelers: z.coerce.number().int().min(1, { message: 'É necessário pelo menos 1 viajante.' }),
  passengers: z.array(z.object({
    name: z.string().min(3, { message: 'O nome do passageiro deve ter pelo menos 3 caracteres.' }),
    cpf: z.string().regex(/^\d{3}\.\d{3}\.\d{3}-\d{2}$/, { message: 'CPF inválido. Use o formato XXX.XXX.XXX-XX.' }),
  })).min(1, { message: 'É necessário adicionar pelo menos um passageiro.' })
});

// Ação de reserva final com transações no banco de dados
export async function submitReservation(prevState: any, formData: FormData) {
    const cookieStore = cookies();
    const supabase = createRouteHandlerClient({ cookies: () => cookieStore });

    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
        return { message: 'Acesso negado. Por favor, faça login para continuar.', errors: {}, success: false };
    }
    
    const passengers = [];
    let i = 0;
    while (formData.has(`passengers[${i}][name]`)) {
        passengers.push({
            name: formData.get(`passengers[${i}][name]`),
            cpf: formData.get(`passengers[${i}][cpf]`),
        });
        i++;
    }

    const validatedFields = CreateReservationSchema.safeParse({
        packageId: formData.get('packageId'),
        numTravelers: formData.get('numTravelers'),
        passengers: passengers,
    });

    if (!validatedFields.success) {
        const flattenedErrors = {};
        for (const issue of validatedFields.error.issues) {
            flattenedErrors[issue.path.join('.')] = issue.message;
        }
        return { message: 'Falha na validação. Verifique os campos.', errors: flattenedErrors, success: false };
    }
    
    const { packageId, numTravelers } = validatedFields.data;

    try {
        // 1. Buscar dados do pacote (preço e disponibilidade) do servidor para segurança
        const { data: travelPackage, error: packageError } = await supabase
            .from('viagens')
            .select('preco, disponibilidade')
            .eq('id', packageId)
            .single();

        if (packageError || !travelPackage) {
            return { message: "Pacote de viagem não encontrado ou inválido.", success: false, errors: {} };
        }

        // 2. Verificar disponibilidade
        if (travelPackage.disponibilidade < numTravelers) {
            return { message: `Desculpe, restam apenas ${travelPackage.disponibilidade} vagas.`, success: false, errors: {} };
        }

        const serverCalculatedTotal = travelPackage.preco * numTravelers;

        // 3. Inserir a reserva na tabela `reservas`
        const { data: reservation, error: reservationError } = await supabase
            .from('reservas')
            .insert({
                usuario_id: user.id,
                viagem_id: packageId,
                quantidade_passagens: numTravelers,
                valor_total: serverCalculatedTotal,
                status: 'pendente', // Começa como pendente
                metodo_pagamento: 'credit_card_simulation'
            })
            .select('id')
            .single();
        
        if (reservationError || !reservation) {
            throw new Error('Não foi possível criar o registro da reserva.');
        }

        // 4. Inserir o pagamento na tabela `pagamentos` (simulação)
        const { error: paymentError } = await supabase
            .from('pagamentos')
            .insert({
                reserva_id: reservation.id,
                valor: serverCalculatedTotal,
                metodo: 'Cartão de Crédito (Simulado)',
                status: 'aprovado'
            });

        if (paymentError) {
            // Opcional: deletar a reserva se o pagamento falhar
            throw new Error('Falha ao registrar o pagamento.');
        }
        
        // 5. Atualizar o status da reserva para 'confirmada'
        const { error: updateStatusError } = await supabase
            .from('reservas')
            .update({ status: 'confirmada' })
            .eq('id', reservation.id);

        if (updateStatusError) {
            throw new Error('Falha ao confirmar o status da reserva.');
        }

        // 6. Atualizar (decrementar) a disponibilidade do pacote
        const newAvailability = travelPackage.disponibilidade - numTravelers;
        const { error: updateAvailabilityError } = await supabase
            .from('viagens')
            .update({ disponibilidade: newAvailability })
            .eq('id', packageId);
        
        if (updateAvailabilityError) {
            // Cenário complexo: A reserva foi feita, mas a disponibilidade não foi atualizada.
            // Requer uma estratégia de reconciliação, mas por agora vamos apenas logar.
            console.error(`CRÍTICO: Falha ao atualizar disponibilidade do pacote ${packageId}.`);
        }

        // 7. Revalidar caches para atualizar a UI
        revalidatePath(`/packages/${packageId}`);
        revalidatePath('/my-trips');

        return {
            message: `Reserva para ${numTravelers} pessoa(s) confirmada com sucesso! Você já pode visualizá-la em "Minhas Viagens".`,
            errors: {},
            success: true,
        };

    } catch (e) {
        console.error("Erro no processamento da reserva:", e.message);
        return {
            message: e.message || 'Ocorreu um erro inesperado no servidor. Tente novamente mais tarde.',
            errors: {},
            success: false,
        };
    }
}
